using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace LoopFive {
 public static partial class Theme {
  public static readonly string[] Names={"Carbon · original","Aurora · violeta","Ocean · azul","Ember · cobre","Studio · claro","Inferno · fuego"};
  public static Color Accent=Color.FromArgb(69,235,184),Surface=Color.FromArgb(21,26,33);public static bool Animate=true;
  static Color Hex(int n){return Color.FromArgb((n>>16)&255,(n>>8)&255,n&255);}
  public static void Configure(SystemConfig c){int i=Array.IndexOf(Names,c.UiTheme);if(i<0)i=0;int[] bg={0x0c1015,0x100e1c,0x09141d,0x19110e,0xe8edf3,0x100b10},panel={0x191f28,0x211b32,0x132735,0x2a201b,0xffffff,0x23141d},accent={0x45ebb8,0xb89aff,0x55cfff,0xffb36a,0x176f8c,0xff869f};Background=Hex(bg[i]);Panel=Hex(panel[i]);Surface=Blend(Background,Panel,.5f);Line=i==4?Hex(0xc4cfdc):Blend(Panel,Color.White,.12f);Text=i==4?Hex(0x162637):Hex(0xeaf0f8);Muted=i==4?Hex(0x526577):Hex(0x98a8be);Accent=Hex(accent[i]);if(c.UiAccent!=null&&c.UiAccent.Length==7){try{Color a=ColorTranslator.FromHtml(c.UiAccent);float brightness=a.GetBrightness();if(brightness>.12&&brightness<.9)Accent=a;}catch{}}Green=i==4?Hex(0x087d50):Hex(0x1feb8f);Red=i==4?Hex(0xbf2445):Hex(0xff405c);Amber=i==4?Hex(0x926000):Hex(0xffb941);Blue=i==4?Hex(0x186ab6):Hex(0x48a4ff);Animate=!c.ReduceMotion;}
  public static Color Blend(Color a,Color b,float t){return Color.FromArgb((int)(a.R+(b.R-a.R)*t),(int)(a.G+(b.G-a.G)*t),(int)(a.B+(b.B-a.B)*t));}
  public static GraphicsPath Round(RectangleF r,float radius){float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));GraphicsPath p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static void ApplyTree(Control root){root.SuspendLayout();ApplyControl(root);root.ResumeLayout();root.Invalidate(true);}
  static void ApplyControl(Control c){if(c is HardwareKnob){c.BackColor=Color.Transparent;c.ForeColor=Text;c.Invalidate();return;}c.BackColor=c is TrackStrip||c is Fader||c is FxBar||c is Button||c is TextBoxBase||c is NumericUpDown||c is ComboBox?Panel:Background;c.ForeColor=c is Label?Muted:Text;if(c is Label&&c.Parent is HardwareSurface)c.BackColor=Color.Transparent;if(c is Fader)c.BackColor=Color.FromArgb(12,13,17);Button b=c as Button;if(b!=null){b.FlatAppearance.BorderColor=Line;b.FlatAppearance.MouseOverBackColor=Blend(Panel,Accent,.13f);b.FlatAppearance.MouseDownBackColor=Blend(Panel,Accent,.25f);}DataGridView grid=c as DataGridView;if(grid!=null){grid.BackgroundColor=Background;grid.GridColor=Line;grid.DefaultCellStyle.BackColor=Panel;grid.DefaultCellStyle.ForeColor=Text;grid.DefaultCellStyle.SelectionBackColor=Blend(Panel,Accent,.28f);grid.DefaultCellStyle.SelectionForeColor=Text;grid.ColumnHeadersDefaultCellStyle.BackColor=Surface;grid.ColumnHeadersDefaultCellStyle.ForeColor=Text;grid.EnableHeadersVisualStyles=false;}foreach(Control child in c.Controls)ApplyControl(child);c.Invalidate();}
 }
 public class DeckTabs:TabControl {
  public DeckTabs(){DrawMode=TabDrawMode.OwnerDrawFixed;SizeMode=TabSizeMode.Fixed;ItemSize=new Size(155,36);Padding=new Point(14,8);SetStyle(ControlStyles.OptimizedDoubleBuffer,true);}
  protected override void WndProc(ref Message m){base.WndProc(ref m);if((m.Msg==15||m.Msg==0x318||m.Msg==0x317)&&IsHandleCreated){using(Graphics g=m.Msg==15?Graphics.FromHwnd(Handle):Graphics.FromHdc(m.WParam)){using(Brush b=new SolidBrush(Theme.Background)){int right=TabCount==0?0:GetTabRect(TabCount-1).Right+2;g.FillRectangle(b,right,0,Math.Max(0,Width-right),ItemSize.Height+4);}using(Pen p=new Pen(Theme.Background,4)){g.DrawLine(p,1,ItemSize.Height+2,1,Height);g.DrawLine(p,Width-2,ItemSize.Height+2,Width-2,Height);g.DrawLine(p,0,Height-2,Width,Height-2);g.DrawLine(p,0,ItemSize.Height+3,Width,ItemSize.Height+3);}}}}
  protected override void OnDrawItem(DrawItemEventArgs e){bool selected=e.Index==SelectedIndex;Rectangle r=GetTabRect(e.Index);r.Inflate(1,1);using(Brush b=new SolidBrush(selected?Theme.Panel:Theme.Background))e.Graphics.FillRectangle(b,r);TextRenderer.DrawText(e.Graphics,Language.T(TabPages[e.Index].Text),Theme.Small,r,selected?Theme.Accent:Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(selected)using(Brush b=new SolidBrush(Theme.Accent))e.Graphics.FillRectangle(b,r.X+12,r.Bottom-3,r.Width-24,3);}
 }
}
namespace LoopFive {
 public class DeckButton:System.Windows.Forms.Button {
  public DeckButton(){SetStyle(System.Windows.Forms.ControlStyles.UserPaint|System.Windows.Forms.ControlStyles.AllPaintingInWmPaint|System.Windows.Forms.ControlStyles.OptimizedDoubleBuffer,true);Cursor=System.Windows.Forms.Cursors.Hand;}
  protected override void OnPaint(System.Windows.Forms.PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.Clear(Parent==null?Theme.Background:Parent.BackColor);bool hover=ClientRectangle.Contains(PointToClient(System.Windows.Forms.Control.MousePosition));var r=new System.Drawing.Rectangle(1,1,Width-3,Height-3);if(r.Width<2||r.Height<2)return;using(var p=Theme.Round(r,6)){using(var b=new System.Drawing.SolidBrush(hover?Theme.Blend(Theme.Panel,Theme.Accent,.14f):BackColor))g.FillPath(b,p);using(var pen=new System.Drawing.Pen(Focused?Theme.Accent:FlatAppearance.BorderColor))g.DrawPath(pen,p);}System.Windows.Forms.TextRenderer.DrawText(g,Language.T(Text),Font,ClientRectangle,Enabled?ForeColor:Theme.Muted,System.Windows.Forms.TextFormatFlags.HorizontalCenter|System.Windows.Forms.TextFormatFlags.VerticalCenter|System.Windows.Forms.TextFormatFlags.EndEllipsis);}
 }
